def bfs_with_levels(graph, start):
    """BFS that shows nodes at each level"""
    visited = {start}
    levels = {0: [start]}
    current_level = 0

    while levels[current_level]:
        next_level = []
        for node in levels[current_level]:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_level.append(neighbor)

        current_level += 1
        levels[current_level] = next_level
        if not next_level:
            break

    return levels

